pub fn edit(&mut self, scene: &mut Scene, action: impl FnOnce(&mut Scene)) {
    let before = scene.clone();
    action(scene);
    if self.undo.len() == LIMIT {
        self.undo.remove(0);
    }
    self.undo.push(before);
    self.redo.clear();
}

